import { createRouter, createWebHistory } from 'vue-router'
import Dashboard from '../views/Dashboard.vue'
import OpenPositions from '../views/OpenPositions.vue'
import ClosedPositions from '../views/ClosedPositions.vue'
import Transactions from '../views/Transactions.vue'
import Profile from '../views/Profile.vue'
import Database from '../views/Database.vue'
import Brokers from '../views/Brokers.vue'
import Securities from '../views/Securities.vue'
import Prices from '../views/Prices.vue'

const routes = [
  {
    path: '/dashboard',
    name: 'Dashboard',
    component: Dashboard
  },
  {
    path: '/open-positions',
    name: 'OpenPositions',
    component: OpenPositions
  },
  {
    path: '/closed-positions',
    name: 'ClosedPositions',
    component: ClosedPositions
  },
  {
    path: '/transactions',
    name: 'Transactions',
    component: Transactions
  },
  {
    path: '/profile',
    name: 'Profile',
    component: Profile
  },
  {
    path: '/database',
    name: 'Database',
    component: Database,
    children: [
      {
        path: '/brokers',
        name: 'Brokers',
        component: Brokers
      },
      {
        path: '/securities',
        name: 'Securities',
        component: Securities
      },
      {
        path: '/prices',
        name: 'Prices',
        component: Prices
      }
    ]
  }
]

const router = createRouter({
  history: createWebHistory(process.env.BASE_URL),
  routes
})

export default router
